  'export-luts': ['File', 'Records the visible adjustment layers as color lookup tables in .cube, .3dl and .csp files at 17, 33 or 65 points per side, delivered as one file or a zip. Layer masks are ignored.', 'Use when a look built from adjustment layers must be applied in video or grading software.', 'r'],
  'generate-image-assets': ['File', 'Writes the image files for every layer or folder whose name holds an asset name such as hero.png, or a list like 200% big.png, small.jpg60%, 64x? icon.png, logo.svg (a shape layer as a vector file), each trimmed and scaled to its size: in the desktop app into a "[document] assets" folder beside the document, in the web build as a zip.', 'Use when layers are named for the web files they should become and all of them are needed at once.', 'r'],
  'generate-image-assets-folder': ['File', 'Writes the image files for every layer or folder named like hero.png straight into a folder the person chooses, instead of a zip; needs a browser that can write to a folder.', 'Use when the web files should land in a project folder without unzipping.', 'r'],
