const lower = (s: string): string => s.charAt(0).toLowerCase() + s.slice(1);
const plain = (s: string): string => s.replace(/\.\.\.$/, '').replace(/^(New|Add) /, '');

type Family = (id: string, label: string) => CommandMeta | null;
const FAMILIES: Array<[RegExp, Family]> = [
  [/^pick-layer-\d$/, (_, label) => ({ group: 'Layer', description: `Selects the layer ${label || 'in this slot'} from the layers under the pointer (right-click the canvas with the Move tool).`, when: 'Use when you want to select a layer by clicking where it shows on the canvas.', mutates: false })],
  [/^recent-\d+$/, (id, label) => ({ group: 'File', description: `Opens the recent project ${label || 'in this slot'}.`, when: 'Use when you want to reopen a project from the Open Recent list.', mutates: false })],
  [/^new-adj-/, (_, label) => ({ group: 'Layer', description: `Adds a ${plain(label)} adjustment layer; its dialog opens for the values.`, when: `Use when you want ${lower(plain(label))} that stays editable and reversible.`, mutates: true })],
  [/^adj-/, (_, label) => ({ group: 'Image', description: `Opens ${plain(label)} and applies it to the pixels of the active layer.`, when: `Use when ${lower(plain(label))} should be baked into the pixels; adjust.apply sets exact values without the dialog.`, mutates: true })],
  [/^filter-/, (_, label) => ({ group: 'Filter', description: `Opens the ${plain(label)} filter on the active layer.`, when: `Use when you want ${plain(label)} tuned by eye; filter.apply runs it with exact values.`, mutates: true })],
  [/^theme-/, (_, label) => ({ group: 'Window', description: `Switches the window to the ${plain(label.replace(/^Theme: /, ''))} theme; nothing in the window is rebuilt.`, when: 'Use when you want a different window look from the Window > Theme list; start with --no-skin to begin with the default look.', mutates: false })],
  [/^plugin:/, (_, label) => ({ group: 'Plugins', description: `Runs the plugin command ${label}.`, when: 'Use when a plugin you turned on offers this step.', mutates: true })],
];

export function metaFor(id: string, label: string): CommandMeta | null {
  const row = ROWS[id];
  if (row) return { group: row[0], description: row[1], when: row[2], mutates: !!row[3]?.includes('m'), risky: !!row[3]?.includes('r') };
  for (const [re, make] of FAMILIES) if (re.test(id)) return make(id, label);
  return null;
}
